def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def parsear_duracion(s):
    if not s:
        return 0
    minutos = 0
    for char in s:
        if char.isdigit():
            minutos += int(char)
        elif char == 'h':
            minutos += 60
        elif char == 'm':
            minutos += 1
    return minutos

def es_palindromo(s):
    cleaned = ''.join([char for char in s if char.isalnum() and char not in '.,!?;:()[]{}' and char.isupper()])
    return cleaned == cleaned[::-1]

def aplanar(lista):
    result = []
    for item in lista:
        if isinstance(item, list):
            result.extend(aplanar(item))
        else:
            result.append(item)
    return result

def buscar(lista, x):
    izquierda = 0
    derecha = len(lista) - 1
    while izquierda <= derecha:
        medio = (izquierda + derecha) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            izquierda = medio + 1
        else:
            derecha = medio - 1
    return -1

def agrupar_por(items, clave):
    agrupados = {}
    for item in items:
        if item[clave] not in agrupados:
            agrupados[item[clave]] = []
        agrupados[item[clave]].append(item)
    return agrupados

def contar_palabras(texto):
    import re
    palabras = re.findall(r'\b\w+\b', texto.lower())
    diccionario = {}
    for palabra in palabras:
        if palabra not in diccionario:
            diccionario[palabra] = 0
        diccionario[palabra] += 1
    return diccionario

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    if n < 0:
        n += len(lista)
    return lista[-n:] + lista[:-n]

def a_romano(n):
    if n < 1 or n > 3999:
        raise ValueError("El número debe estar entre 1 y 3999")

    numeros = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    letras = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]

    resultado = []
    for i, num in enumerate(numeros):
        while n >= num:
            resultado.append(letras[i])
            n -= num

    return "".join(reversed(resultado))

def from_romano(s):
    roman_map = {
        'I': 1, 'V': 5, 'X': 10,
        'L': 50, 'C': 100,
        'D': 500, 'M': 1000
    }
    result = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_map.get(char, 0)
        if value < prev_value:
            result -= value
        else:
            result += value
        prev_value = value
    return result

def mayor_racha(lista):
    if not lista:
        return None

    max_racha = 0
    max_element = None
    current_element = None
    current_racha = 0

    for i in range(len(lista)):
        if i == 0:
            current_element = lista[i]
            current_racha = 1
        else:
            if lista[i] == current_element:
                current_racha += 1
            else:
                if current_racha > max_racha:
                    max_racha = current_racha
                    max_element = current_element
                current_element = lista[i]
                current_racha = 1

    if current_racha > max_racha:
        max_racha = current_racha
        max_element = current_element

    return (max_element, max_racha)

def a_camel(s):
    if not s:
        return ""
    words = s.split()
    result = []
    for word in words:
        if word == words[0]:
            result.append(word)
        else:
            result.append(word[0].upper() + word[1:])
    return "".join(result)

def a_snake(s):
    if not s:
        return ""
    result = []
    for i, char in enumerate(s):
        if char.isupper() and i > 0 and s[i-1].islower():
            result.append("_")
        result.append(char.lower())
    return "".join(result)

def primos(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False
    return [i for i in range(2, n + 1) if is_prime[i]]

def mcd(a, b):
    if a == 0:
        return b
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def comprimir(s):
    if not s:
        return s
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1
    compressed = ""
    for char, count in counts.items():
        compressed += char * count
        if len(compressed) > len(s):
            return s
    return compressed

def balanceado(s):
    if not s:
        return True
    stack = []
    for char in s:
        if char in '([{':
            stack.append(char)
        elif char == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()
        elif char == ']':
            if not stack or stack[-1] != '[':
                return False
            stack.pop()
        elif char == '}':
            if not stack or stack[-1] != '{':
                return False
            stack.pop()
    return len(stack) == 0

