def fusionar(intervalos):
    if not intervals:
        return []

    # Ordenar los intervalos por inicio
    intervals = sorted(intervals, key=lambda x: x[0])

    resultado = [intervalos[0]]

    for intervalo in intervalos[1:]:
        ultimo = resultado[-1]
        if intervalo[0] <= ultimo[1]:
            # Se tocan o se superponen, se fusionan
            ultimo[1] = max(ultimo[1], intervalo[1])
        else:
            # No se tocan, se agrega como nuevo intervalo
            resultado.append(intervalo)

    return resultado

def balanced(s):
    stack = []
    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if (top == '(' and char == ')') or \
               (top == '[' and char == ']') or \
               (top == '{' and char == '}'):
                continue
            else:
                return False
    return len(stack) == 0

def mediana(nums):
    if not nums:
        return None
    sorted_nums = sorted(nums)
    n = len(sorted_nums)
    if n % 2 == 1:
        return sorted_nums[n // 2]
    else:
        return (sorted_nums[n // 2 - 1] + sorted_nums[n // 2]) / 2

def top_frecuentes(texto, k):
    word_counts = {}
    for word in texto.split():
        word = word.lower()
        if word:
            word_counts[word] = word_counts.get(word, 0) + 1

    sorted_words = sorted(word_counts.items(), key=lambda x: (-x[1], x[0]))
    return sorted_words[:k]

