def formatear_bytes(n):
    if n < 0:
        return "Error: El número de bytes no puede ser negativo"

    unidad = "B"
    valor = n

    if valor >= 1024:
        unidad = "KB"
        valor = valor / 1024
    elif valor >= 1024**2:
        unidad = "MB"
        valor = valor / (1024**2)
    elif valor >= 1024**3:
        unidad = "GB"
        valor = valor / (1024**3)

    if valor == int(valor):
        return f"{int(valor)} {unidad}"
    else:
        return f"{valor:.1f} {unidad}"

