def contar_islas(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                count += 1
                # Recorrer todos los vecinos conectados (arriba, abajo, izquierda, derecha)
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                        grid[nr][nc] = 0  # Marcar como visitado para evitar contar múltiples veces
    return count

def distancia(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])

    return dp[m][n]

import re

def validar_password(p):
    if len(p) < 8:
        return False
    if not re.search(r'[A-Z]', p):
        return False
    if not re.search(r'[a-z]', p):
        return False
    if not re.search(r'\d', p):
        return False
    if not re.search(r'[^A-Za-z0-9]', p):
        return False
    return True

def a_base(n, base):
    if n == 0:
        return '0'
    digits = '0123456789abcdef'
    result = ''
    while n > 0:
        remainder = n % base
        result = digits[remainder] + result
        n //= base
    return result

def pares_primero(nums):
    pares = []
    impares = []
    for num in nums:
        if num % 2 == 0:
            pares.append(num)
        else:
            impares.append(num)
    return pares + impares

